static int mn(int a,int b){return a<b?a:b;} static int mx(int a,int b){return a>b?a:b;}
static int vr(struct qm_rect r){return r.w>0&&r.h>0&&r.w<=4096&&r.h<=4096;}
static int inr(struct qm_rect r,int x,int y){return x>=r.x&&y>=r.y&&x<r.x+r.w&&y<r.y+r.h;}
static int vi(const struct qm_item *a,int n){int i,j;if(!a||n<1||n>32)return 0;for(i=0;i<n;i++){if(!a[i].id)return 0;for(j=0;j<i;j++)if(a[i].id==a[j].id)return 0;}return 1;}
static qm_u32 mask(int n){return n==32?~(qm_u32)0:(((qm_u32)1<<n)-1);}
static qm_color al(qm_color c,unsigned a){return(c&0xffffffu)|((((c>>24)*a/255u)&255u)<<24);}
static void txt(struct qm_context *c,struct qm_rect r,const char *s,qm_color col,int center){int x,y;if(!s||!vr(r))return;x=r.x+(center?(r.w-qm_text_width(c,s))/2:0);y=r.y+(r.h-qm_font_height(c))/2;if(qm_clip_push(c,r)){qm_text(c,x,y,s,col);qm_clip_pop(c);}}
static void icon_or_text(struct qm_context *c,struct qm_rect r,const char *token,qm_color col){enum qm_icon icon;if(!token)return;if(qm_icon_from_token(token,&icon))qm_draw_icon(c,icon,r,col);else txt(c,r,token,col,1);}
static void fb(struct qm_context*c,struct qm_rect r,unsigned st,int rad,qm_color col){if(st&QM_HELD)qm_round_rect(c,r,rad,al(col,31));else if(st&QM_HOVERED)qm_round_rect(c,r,rad,al(col,20));if(st&QM_FOCUSED)qm_stroke_rect(c,r,rad,2,c->theme.primary);}
static struct qm_rect cell(struct qm_rect r,int i,int n,int v){int a=(int)((qm_s64)(v?r.h:r.w)*i/n),b=(int)((qm_s64)(v?r.h:r.w)*(i+1)/n);if(v){r.y+=a;r.h=b-a;}else{r.x+=a;r.w=b-a;}return r;}
static void focus_move(struct qm_context*c,const struct qm_item*a,int n,int v){int i,p=-1,d=0,t=-1;if(!c||!c->input_enabled)return;for(i=0;i<n;i++)if(a[i].id==c->focused_id)p=i;if(p<0)return;if(c->input.key==QM_KEY_HOME){for(i=0;i<n;i++)if(!a[i].disabled){t=i;break;}}else if(c->input.key==QM_KEY_END){for(i=n-1;i>=0;i--)if(!a[i].disabled){t=i;break;}}else{if(c->input.key==(v?QM_KEY_UP:QM_KEY_LEFT))d=-1;if(c->input.key==(v?QM_KEY_DOWN:QM_KEY_RIGHT))d=1;if(!d)return;for(i=1;i<=n;i++){int q=(p+d*i+n)%n;if(!a[q].disabled){t=q;break;}}}c->input.key=QM_KEY_NONE;if(t>=0)c->focused_id=a[t].id;}
void qm_stack_init(struct qm_stack*s,struct qm_rect r,int v,int gap){if(!s)return;s->bounds=vr(r)?r:(struct qm_rect){0,0,0,0};s->vertical=!!v;s->gap=mx(0,mn(gap,4096));s->offset=0;}
struct qm_rect qm_stack_next(struct qm_stack*s,int e){struct qm_rect r={0,0,0,0};int total;if(!s||e<=0||!vr(s->bounds))return r;total=s->vertical?s->bounds.h:s->bounds.w;if(s->offset>=total)return r;e=mn(e,total-s->offset);r=s->bounds;if(s->vertical){r.y+=s->offset;r.h=e;}else{r.x+=s->offset;r.w=e;}s->offset+=e+s->gap;return r;}
int qm_navigation(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,int*sel,enum qm_navigation_style style){int i,ch=0;if(!c||!sel||!vr(r)||!vi(a,n))return 0;focus_move(c,a,n,style!=QM_NAV_BAR);qm_fill(c,r,c->theme.surface_container);for(i=0;i<n;i++){struct qm_rect q=cell(r,i,n,style!=QM_NAV_BAR),p;qm_color col;unsigned st;if(!vr(q))continue;st=qm_interact(c,a[i].id,q,!a[i].disabled);if(st&QM_ACTIVATED){*sel=i;ch=1;}col=*sel==i?c->theme.on_secondary_container:c->theme.on_surface_variant;if(a[i].disabled)col=al(col,97);if(style==QM_NAV_DRAWER){p=q;p.x+=8;p.y+=4;p.w-=16;p.h-=8;if(*sel==i)qm_round_rect(c,p,12,c->theme.secondary_container);fb(c,p,st,12,col);p.x+=12;p.w-=24;txt(c,p,a[i].label,col,0);}else{p.w=mn(64,mx(1,q.w-8));p.h=mn(32,mx(1,q.h-qm_font_height(c)-8));p.x=q.x+(q.w-p.w)/2;p.y=q.y+mx(0,(q.h-p.h-qm_font_height(c)-4)/2);if(*sel==i)qm_round_rect(c,p,p.h/2,c->theme.secondary_container);fb(c,p,st,p.h/2,col);icon_or_text(c,p,a[i].icon,col);p.y+=p.h+2;p.h=qm_font_height(c);p.x=q.x;p.w=q.w;txt(c,p,a[i].label,col,1);}if(a[i].badge)qm_badge(c,p.x+p.w-4,p.y+4,a[i].badge);}return ch;}
int qm_tabs(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,int*sel){int i,ch=0;if(!c||!sel||!vr(r)||!vi(a,n))return 0;focus_move(c,a,n,0);qm_fill(c,r,c->theme.surface);for(i=0;i<n;i++){struct qm_rect q=cell(r,i,n,0),u;qm_color col;unsigned st;if(!vr(q))continue;st=qm_interact(c,a[i].id,q,!a[i].disabled);if(st&QM_ACTIVATED){*sel=i;ch=1;}col=*sel==i?c->theme.primary:c->theme.on_surface_variant;if(a[i].disabled)col=al(col,97);fb(c,q,st,0,col);txt(c,q,a[i].label,col,1);if(*sel==i){u=q;u.y+=q.h-3;u.h=3;qm_round_rect(c,u,2,c->theme.primary);}}return ch;}
static int grp(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,int*sel,qm_u32*bits,int allow,enum qm_group_style style){int i,ch=0;if(!c||(!sel&&!bits)||!vr(r)||!vi(a,n))return 0;focus_move(c,a,n,0);for(i=0;i<n;i++){struct qm_rect q=cell(r,i,n,0);unsigned st;int on;qm_color bg,fg;if(!vr(q))continue;st=qm_interact(c,a[i].id,q,!a[i].disabled);if(st&QM_ACTIVATED){if(sel){*sel=i;ch=1;}if(bits){qm_u32 b=*bits^((qm_u32)1<<i);if(allow||b&mask(n)){*bits=b;ch=1;}}}on=sel?*sel==i:!!(*bits&((qm_u32)1<<i));bg=on?c->theme.primary:c->theme.secondary_container;fg=on?c->theme.on_primary:c->theme.on_secondary_container;if(style==QM_GROUP_TONAL&&on){bg=c->theme.primary_container;fg=c->theme.on_primary_container;}if(style==QM_GROUP_OUTLINED&&!on)bg=c->theme.surface;if(a[i].disabled)fg=al(fg,97);qm_round_rect(c,q,q.h/2,bg);if(style==QM_GROUP_OUTLINED)qm_stroke_rect(c,q,q.h/2,1,c->theme.outline);fb(c,q,st,q.h/2,fg);txt(c,q,a[i].label,fg,1);}return ch;}
int qm_segmented(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,int*s){return grp(c,r,a,n,s,0,1,QM_GROUP_TONAL);}int qm_multi_segmented(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,qm_u32*b,int allow){return grp(c,r,a,n,0,b,allow,QM_GROUP_TONAL);}int qm_button_group(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,int*s,enum qm_group_style st){return grp(c,r,a,n,s,0,1,st);}int qm_multi_button_group(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,qm_u32*b,int allow,enum qm_group_style st){return grp(c,r,a,n,0,b,allow,st);}
int qm_toolbar(struct qm_context*c,struct qm_rect r,const struct qm_item*a,int n,qm_u32*tog,int vert,int vibrant){int i,act=-1;if(!c||!vr(r)||!vi(a,n))return -1;focus_move(c,a,n,vert);qm_round_rect(c,r,mn(r.w,r.h)/2,vibrant?c->theme.primary_container:c->theme.surface_container_high);r.x+=8;r.y+=8;r.w-=16;r.h-=16;if(!vr(r))return -1;for(i=0;i<n;i++){struct qm_rect q=cell(r,i,n,vert);unsigned st;qm_color col=vibrant?c->theme.on_primary_container:c->theme.on_surface;if(!vr(q))continue;st=qm_interact(c,a[i].id,q,!a[i].disabled);if(st&QM_ACTIVATED){act=i;if(tog)*tog^=(qm_u32)1<<i;}if(tog&&(*tog&((qm_u32)1<<i)))qm_round_rect(c,q,mn(q.w,q.h)/2,c->theme.surface);if(a[i].disabled)col=al(col,97);fb(c,q,st,mn(q.w,q.h)/2,col);icon_or_text(c,q,a[i].icon?a[i].icon:a[i].label,col);}return act;}
enum qm_split_action qm_split_button(struct qm_context*c,struct qm_rect r,qm_u32 pid,qm_u32 mid,const char*s,int*expanded,int enabled){struct qm_rect p,m;unsigned a,b;qm_color col;if(!c||!s||!expanded||!pid||!mid||pid==mid||!vr(r))return QM_SPLIT_NONE;m=r;m.w=mn(48,r.w/3);m.x=r.x+r.w-m.w;p=r;p.w=m.x-r.x-2;a=qm_interact(c,pid,p,enabled);b=qm_interact(c,mid,m,enabled);col=enabled?c->theme.on_primary:al(c->theme.on_primary,97);qm_round_rect(c,p,r.h/2,c->theme.primary);qm_round_rect(c,m,*expanded?8:r.h/2,c->theme.primary);fb(c,p,a,r.h/2,col);fb(c,m,b,*expanded?8:r.h/2,col);txt(c,p,s,col,1);if(b&QM_ACTIVATED){*expanded=!*expanded;return QM_SPLIT_MENU;}return(a&QM_ACTIVATED)?QM_SPLIT_PRIMARY:QM_SPLIT_NONE;}
void qm_card_surface(struct qm_context*c,struct qm_rect r,enum qm_card_style st){if(!c||!vr(r))return;qm_round_rect(c,r,12,st==QM_CARD_OUTLINED?c->theme.surface:st==QM_CARD_ELEVATED?c->theme.surface_container_high:c->theme.surface_container);if(st==QM_CARD_OUTLINED)qm_stroke_rect(c,r,12,1,c->theme.outline_variant);}
