int qm_list_item(struct qm_context*c,qm_u32 id,struct qm_rect r,const char*h,const char*s,const char*trail,int selected,int enabled){struct qm_rect t,u;unsigned z;int tw=0;if(!c||!id||!vr(r))return 0;z=qm_interact(c,id,r,enabled);qm_fill(c,r,selected?c->theme.secondary_container:c->theme.surface);fb(c,r,z,0,c->theme.on_surface);t=r;t.x+=16;t.w-=32;if(trail){tw=mn(mx(0,t.w/3),qm_text_width(c,trail));u=t;u.x+=u.w-tw;u.w=tw;txt(c,u,trail,c->theme.on_surface_variant,0);t.w-=tw+12;}if(s){t.y=r.y+(r.h-2*qm_font_height(c)-4)/2;t.h=qm_font_height(c);txt(c,t,h,enabled?c->theme.on_surface:al(c->theme.on_surface,97),0);t.y+=t.h+4;txt(c,t,s,c->theme.on_surface_variant,0);}else txt(c,t,h,c->theme.on_surface,0);return !!(z&QM_ACTIVATED);}
void qm_divider(struct qm_context*c,struct qm_rect r,int vert){if(!c||!vr(r))return;if(vert){r.x+=r.w/2;r.w=1;}else{r.y+=r.h/2;r.h=1;}qm_fill(c,r,c->theme.outline_variant);}
void qm_badge(struct qm_context*c,int x,int y,int count){char s[4];struct qm_rect r;if(!c||!count)return;if(count<0){qm_circle(c,x,y,3,c->theme.error);return;}if(count>99){s[0]='9';s[1]='9';s[2]='+';s[3]=0;}else if(count>=10){s[0]=(char)('0'+count/10);s[1]=(char)('0'+count%10);s[2]=0;}else{s[0]=(char)('0'+count);s[1]=0;}r.w=mx(18,qm_text_width(c,s)+8);r.h=mx(18,qm_font_height(c));r.x=x-r.w/2;r.y=y-r.h/2;qm_round_rect(c,r,r.h/2,c->theme.error);txt(c,r,s,c->theme.on_error,1);}
static const short sin64[64]={0,100,200,297,392,483,569,650,724,792,851,903,946,980,1004,1019,1024,1019,1004,980,946,903,851,792,724,650,569,483,392,297,200,100,0,-100,-200,-297,-392,-483,-569,-650,-724,-792,-851,-903,-946,-980,-1004,-1019,-1024,-1019,-1004,-980,-946,-903,-851,-792,-724,-650,-569,-483,-392,-297,-200,-100};
