void qm_linear_progress(struct qm_context*c,struct qm_rect r,int val,unsigned phase,int wavy){int y,x,end,start=0,amp,px,py;if(!c||!vr(r))return;y=r.y+r.h/2;{struct qm_rect t={r.x,y-2,r.w,mn(4,r.h)};qm_round_rect(c,t,2,c->theme.secondary_container);}if(val<0){int span=mx(1,r.w/3);start=(int)((qm_s64)(r.w+span)*(phase&1023)/1024)-span;end=mn(r.w,start+span);start=mx(0,start);}else end=(int)((qm_s64)r.w*mn(val,1000)/1000);if(end<=start)return;amp=wavy&&(val<0||(val>100&&val<950))?mn(3,(r.h-1)/2):0;px=r.x+start;py=y+amp*sn((unsigned)(start*1024/40)+(phase&1023))/1024;for(x=start+1;x<=end;x++){int ny=y+amp*sn((unsigned)(x*1024/40)+(phase&1023))/1024;qm_line(c,px,py,r.x+x,ny,mn(4,r.h),c->theme.primary);px=r.x+x;py=ny;}}
