static int panel(struct qm_context*c,struct qm_rect view,struct qm_rect p,int*open,int dismiss){if(!c||!open||!*open||!vr(view)||!vr(p))return 0;if(dismiss&&c->input_enabled&&(c->input.key==QM_KEY_ESCAPE||(c->input.pressed&&inr(view,c->input.x,c->input.y)&&!inr(p,c->input.x,c->input.y)))){*open=0;c->active_id=0;c->input.key=QM_KEY_NONE;return 0;}qm_fill(c,view,0x52000000u);return 1;}
int qm_dialog_panel(struct qm_context*c,struct qm_rect view,struct qm_rect r,const char*title,int*open,int dismiss,struct qm_rect*out){struct qm_rect h;if(!out)return 0;*out=(struct qm_rect){0,0,0,0};if(!panel(c,view,r,open,dismiss))return 0;qm_round_rect(c,r,28,c->theme.surface_container_high);h=r;h.x+=24;h.y+=20;h.w-=48;h.h=qm_font_height(c);txt(c,h,title,c->theme.on_surface,0);*out=r;out->x+=24;out->y=h.y+h.h+16;out->w-=48;out->h=r.y+r.h-24-out->y;if(!vr(*out))out->w=out->h=0;return 1;}
int qm_sheet_panel(struct qm_context*c,struct qm_rect view,enum qm_sheet_side side,int extent,int*open,int dismiss,struct qm_rect*out){struct qm_rect r;if(!out)return 0;*out=(struct qm_rect){0,0,0,0};if(!vr(view)||extent<=0||side<QM_SHEET_BOTTOM||side>QM_SHEET_RIGHT)return 0;r=view;if(side==QM_SHEET_BOTTOM){r.h=mn(extent,r.h);r.y+=view.h-r.h;}else{r.w=mn(extent,r.w);if(side==QM_SHEET_RIGHT)r.x+=view.w-r.w;}if(!panel(c,view,r,open,dismiss))return 0;qm_round_rect(c,r,24,c->theme.surface_container_high);*out=r;out->x+=16;out->y+=16;out->w-=32;out->h-=32;if(!vr(*out))out->w=out->h=0;return 1;}
int qm_snackbar(struct qm_context*c,struct qm_rect r,const char*msg,const char*action,qm_u32 aid,qm_u32 did,int*open,qm_u32*remain,int dismiss){struct qm_rect t,a,x;unsigned as=0,xs=0;int paused;if(!c||!open||!*open||!vr(r)||!msg||(action&&!aid)||(dismiss&&!did)||(action&&dismiss&&aid==did))return 0;qm_round_rect(c,r,4,c->theme.inverse_surface);t=r;t.x+=16;t.w-=32;if(dismiss&&t.w>=32){x=t;x.x+=x.w-32;x.w=32;xs=qm_interact(c,did,x,1);fb(c,x,xs,16,c->theme.inverse_on_surface);txt(c,x,"x",c->theme.inverse_on_surface,1);t.w-=40;if(xs&QM_ACTIVATED)*open=0;}if(action&&t.w>24){a=t;a.w=mn(qm_text_width(c,action)+16,t.w/2);a.x+=t.w-a.w;as=qm_interact(c,aid,a,1);fb(c,a,as,8,c->theme.inverse_on_surface);txt(c,a,action,c->theme.inverse_on_surface,1);t.w-=a.w+8;if(as&QM_ACTIVATED){*open=0;paused=1;}}txt(c,t,msg,c->theme.inverse_on_surface,0);paused=inr(r,c->input.x,c->input.y)||((as|xs)&QM_FOCUSED);if(remain&&*remain&&!paused){if((qm_u32)c->input.dt_ms>=*remain){*remain=0;*open=0;}else *remain-=(qm_u32)c->input.dt_ms;}return !!(as&QM_ACTIVATED);}
